std::atomic<bool> g_new_checkout{false};

void load_flags(const Config& c) {
    g_new_checkout.store(c.get_bool("ff.new_checkout", false),
                        std::memory_order_relaxed);
}

void handle(Request& r) {
    if (g_new_checkout.load(std::memory_order_relaxed)) new_checkout(r);
    else legacy_checkout(r);
}

